CREATE DATABASE IF NOT EXISTS bird_id CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE bird_id;
CREATE TABLE users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,credits INT UNSIGNED NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE payments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,trx_id VARCHAR(120) NULL,invoice_id VARCHAR(120) NOT NULL UNIQUE,amount DECIMAL(10,2) NOT NULL,scans INT UNSIGNED NOT NULL DEFAULT 1,status ENUM('pending','paid','failed','cancelled') NOT NULL DEFAULT 'pending',provider VARCHAR(30) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,paid_at TIMESTAMP NULL,INDEX(user_id),CONSTRAINT fk_payment_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE scan_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,result_text MEDIUMTEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id),CONSTRAINT fk_scan_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
